package ru.neverland.townytreasury.command;
import org.bukkit.command.*;
import org.bukkit.entity.Player;
import com.palmergames.bukkit.towny.TownyAPI;
import java.util.*;
import ru.neverland.townytreasury.NeverLandTownyTreasuryPlus;
import ru.neverland.townytreasury.service.*;
import ru.neverland.townytreasury.gui.TreasuryMenu;
import ru.neverland.townytreasury.model.Week;
import static ru.neverland.townytreasury.service.Ui.tell;
public final class TreasuryCommand implements TabExecutor {
    private final NeverLandTownyTreasuryPlus plugin;private final TreasuryService service;private final TreasuryMenu menu;private final ru.neverland.townytreasury.gui.AsyncDebitMenu debits;
    public TreasuryCommand(NeverLandTownyTreasuryPlus plugin,TreasuryService service,TreasuryMenu menu){this.plugin=plugin;this.service=service;this.menu=menu;debits=new ru.neverland.townytreasury.gui.AsyncDebitMenu(plugin,service);plugin.getServer().getPluginManager().registerEvents(debits,plugin);}
    private String[] clean(String[] args){return args.length>0&&args[0].equalsIgnoreCase("treasury")?Arrays.copyOfRange(args,1,args.length):args;}
    @Override public boolean onCommand(CommandSender sender,Command command,String label,String[] raw){ try (var suiteGuard1 = ru.neverland.core.SuiteState.guard()) {if(ru.neverland.core.SuiteState.frozen("NeverLandTownyTreasuryPlus")){return true;}String[] args=clean(raw);try{
        String action=args.length==0?"menu":args[0].toLowerCase(Locale.ROOT);if(action.equals("reload")){if(!sender.hasPermission("neverlandtownytreasury.admin"))throw new IllegalArgumentException("Нет прав администратора");plugin.reloadTreasury().whenComplete((ok,error)->{if(sender instanceof Player p){if(plugin.isEnabled())ru.neverland.core.SuiteScheduler.entity(plugin,p,()->{if(p.isOnline())tell(p,Boolean.TRUE.equals(ok)?"Настройки казны применены.":"Настройки не применены; проверьте журнал.");});}else plugin.getLogger().info(Boolean.TRUE.equals(ok)?"Настройки казны применены.":"Настройки не применены; проверьте журнал.");});tell(sender,"Проверяем настройки казны…");return true;}
        if(Set.of("requests","request","resolve-request").contains(action)){
            if(!sender.isOp()&&!sender.hasPermission("neverlandtownytreasury.admin"))throw new IllegalArgumentException("Нет прав администратора казны");
            if(action.equals("requests")){if(sender instanceof Player player)debits.open(player,0);else service.asyncDebits().stream().filter(r->!Set.of("PAID","REJECTED").contains(r.get("status"))).limit(100).forEach(r->tell(sender,r.toString()));return true;}
            if(action.equals("request")){if(args.length!=2)throw new IllegalArgumentException("request <UUID>");UUID id=UUID.fromString(args[1]);if(sender instanceof Player player)debits.details(player,id,0,null);else tell(sender,service.debitStatus(id).toString());return true;}
            if(args.length!=4||!Set.of("paid","unpaid").contains(args[2])||!args[3].equals("confirm"))throw new IllegalArgumentException("После проверки точной суммы, города и банковского журнала: resolve-request <UUID> paid|unpaid confirm. Текущий баланс не доказывает отсутствие операции.");
            UUID id=UUID.fromString(args[1]);service.resolveAsync(id,args[2].equals("paid"),sender.getName()).whenComplete((row,error)->{if(sender instanceof Player player)ru.neverland.core.SuiteScheduler.entity(plugin,player,()->{if(player.isOnline()&&(player.isOp()||player.hasPermission("neverlandtownytreasury.admin")))tell(player,error==null?"Квитанция сверена; деньги повторно не переводились.":"Сверка пока не сохранена; проверьте квитанцию.");});else plugin.getLogger().info(error==null?"Сверка квитанции "+id+" сохранена":"Сверка "+id+" не завершена: "+error);});tell(sender,"Результат сверки сохраняется; банковского повтора нет.");return true;
        }
        if(!(sender instanceof Player player))throw new IllegalArgumentException("Откройте команду в игре");if(!player.hasPermission("neverlandtownytreasury.use")&&!player.hasPermission("neverlandtownytreasury.admin"))throw new IllegalArgumentException("Нет доступа к казне");var town=service.town(player);
        if(action.equals("town")){if(!player.hasPermission("neverlandtownytreasury.admin")||args.length!=2)throw new IllegalArgumentException("town <город> — просмотр администратора");town=TownyAPI.getInstance().getTown(args[1]);if(town==null)throw new IllegalArgumentException("Город не найден");menu.open(player,town.getUUID(),null);return true;}
        if(action.equals("resolve")){if(!player.hasPermission("neverlandtownytreasury.admin")||args.length!=4||!Set.of("paid","unpaid").contains(args[3]))throw new IllegalArgumentException("После сверки журнала: resolve <город> <ID счёта> paid|unpaid");var target=TownyAPI.getInstance().getTown(args[1]);if(target==null)throw new IllegalArgumentException("Город не найден");service.resolve(player,target.getUUID(),UUID.fromString(args[2]),args[3].equals("paid")).whenComplete((v,error)->{if(plugin.isEnabled())ru.neverland.core.SuiteScheduler.entity(plugin,player,()->{if(player.isOnline()&&player.hasPermission("neverlandtownytreasury.admin"))tell(player,error==null?"Результат сверки сохранён.":"Сверка не сохранена; проверьте журнал.");});});tell(player,"Сохраняем результат сверки…");return true;}
        if(town==null)throw new IllegalArgumentException("Сначала вступите в город");UUID id=town.getUUID();
        switch(action){case "menu"->menu.open(player,id,null);case "forecast"->{if(args.length>2)throw new IllegalArgumentException("/t treasury forecast [сутки 1–7]");int days=args.length==2?Integer.parseInt(args[1]):1;if(days<1||days>7)throw new IllegalArgumentException("Укажите от 1 до 7 суток");menu.open(player,id,"forecast/"+days);}case "enable","disable","shares","transfer"->menu.prepare(player,id,action,List.of(Arrays.copyOfRange(args,1,args.length)));case "confirm"->{menu.confirm(player,id);}case "history","reports"->menu.open(player,id,action);case "report"->{String week=args.length>1?args[1]:Week.previous(System.currentTimeMillis());menu.open(player,id,"report/"+week);}case "export"->{if(!TreasuryAccess.canExport(player))throw new IllegalArgumentException("Нет права на экспорт CSV");String week=args.length>1?args[1]:Week.previous(System.currentTimeMillis());menu.export(player,id,week);}default->tell(player,"/t treasury [forecast|enable|disable|transfer|shares|confirm|reports|report|history"+(TreasuryAccess.canExport(player)?"|export":"")+"]");}
    }catch(Exception ex){tell(sender,"&c"+ex.getMessage());}return true;} }
    @Override public List<String> onTabComplete(CommandSender sender,Command command,String alias,String[] raw){ try (var suiteGuard2 = ru.neverland.core.SuiteState.guard()) {var args=clean(raw);List<String> options=args.length<=1?List.of("forecast","enable","disable","transfer","shares","confirm","reports","report","export","history","requests","request","resolve-request"):args[0].equalsIgnoreCase("transfer")&&args.length<=3?List.of("construction","army","infrastructure","social","free"):List.of();String prefix=args.length==0?"":args[args.length-1].toLowerCase(Locale.ROOT);return options.stream().filter(s->!s.equals("export")||TreasuryAccess.canExport(sender)).filter(s->!Set.of("requests","request","resolve-request").contains(s)||sender.isOp()||sender.hasPermission("neverlandtownytreasury.admin")).filter(s->s.startsWith(prefix)).toList();} }
}
